        /*vehicle_online=*/false, /*state_stale=*/false);
    RCLCPP_WARN(get_logger(), "VDA 5050 vehicle %s link broken: %s", vehicle_id.c_str(),
                guard.message.c_str());
    if (event_log_) {
      amr_dispatcher_core::dispatcher::MissionEvent evt;
      evt.stamp = "now";
      evt.mission_id = "-";  // 无任务级事件：链路级看门狗告警
