void DispatcherNode::ArchiveMissionRoute(const std::string& mission_id, const Mission& m);
bool DispatcherNode::StartPlanBackend(const DispatchIntent& intent, const std::vector<Pose2D>& waypoints);
bool DispatcherNode::StartActionBackend(const DispatchIntent& intent, const std::vector<Pose2D>& waypoints);
void DispatcherNode::PublishDispatchActiveEvent(const Mission& m);
